import pennylane as qml

dev = qml.device("default.qubit", wires=4)

@qml.qnode(dev)
def circuit(phi, filter):
    # Apply RY rotations
    for i in range(4):
        qml.RY(phi, wires=i)

    # Conditional operations based on filter value
    if filter == 'H':
        qml.Hadamard(wires=0)
    elif filter == 'RY':
        qml.RY(phi, wires=1)
    elif filter == 'CNOT':
        qml.CNOT(wires=[0, 1])

    # Return expectation values of PauliZ
    return [qml.expval(qml.PauliZ(i)) for i in range(4)]

