def compare_circuits(theta1, theta2):
    dev = qml.device('default.qubit', wires=1)

    @qml.qnode(dev)
    def circuit1(theta):
        qml.RX(theta, wires=0)
        return qml.expval(qml.PauliX(0))

    @qml.qnode(dev)
    def circuit2(theta):
        qml.RY(theta, wires=0)
        return qml.expval(qml.PauliX(0))

    expval1 = circuit1(theta1)
    expval2 = circuit2(theta2)

    return abs(expval1 - expval2)

