import torch
import torch.nn as nn
import pennylane as qml

class QuantumCircuit(nn.Module):
    def __init__(self):
        super(QuantumCircuit, self).__init__()
        self.dev = qml.device("default.qubit", wires=3)

    @qml.qnode(self.dev)
    def circuit(self, x):
        qml.BasisState(x, wires=[0, 1, 2])
        qml.Hadamard(wires=0)
        qml.CNOT(wires=[0, 1])
        qml.CNOT(wires=[1, 2])
        return qml.expval(qml.PauliZ(0))

    def forward(self, x):
        return self.circuit(x)

class HybridQuantumNN(nn.Module):
    def __init__(self):
        super(HybridQuantumNN, self).__init__()
        self.quantum_circuit1 = QuantumCircuit()
        self.quantum_circuit2 = QuantumCircuit()

    def forward(self, x):
        output1 = self.quantum_circuit1(x)
        output2 = self.quantum_circuit2(x)
        return output1 + output2

# Example usage
model = HybridQuantumNN()
input_data = torch.tensor([1, 0, 0], dtype=torch.float32)
output = model(input_data)
print(output)

