import pennylane as qml

def process_message(message):
    dev = qml.device("default.qubit", wires=4)

    @qml.qnode(dev)
    def circuit():
        for i in range(4):
            qml.Hadamard(wires=i)
        return qml.state()

    state = circuit()
    processed_message = ''.join([message[i % len(message)] for i in range(len(state))])
    return processed_message

