import pennylane as qml

dev = qml.device("default.qubit", wires=3)

@qml.qnode(dev)
def circuit():
    # Apply Hadamard and T gates
    for wire in range(3):
        qml.Hadamard(wire)
        qml.T(wire)

    # Apply adjoint gates
    for wire in range(3):
