def adjoint_metric_tensor(circuit):
    dev = qml.device("default.qubit", wires=2)

    @qml.qnode(dev)
    def circuit_qnode(params):
        circuit(params)
        return qml.expval(qml.PauliZ(0))

    def postprocess(tapes):
        return np.array([qml.metric_tensor(tape) for tape in tapes])

    tapes = [qml.tape.QuantumTape() for _ in range(2)]
    for i in range(2):
        with tapes[i]:
            qml.RX(np.pi / 4, wires=0)
            qml.RY(np.pi / 4, wires=1)
            qml.CNOT(wires=[0, 1])

    return tapes, postprocess

