def reduce_t_gate_depth(qnode):
    def wrapper(*args, **kwargs):
        # Modify the circuit to reduce T-gate depth
        # This is a simple example that replaces T gates with equivalent operations
        # In practice, you would implement a more sophisticated optimization
        @qml.qnode(qml.device("default.qubit"))
        def optimized_circuit(*params):
            qml.Hadamard(0)
            qml.Hadamard(1)
            qml.CNOT(wires=[0, 1])
            qml.CNOT(wires=[1, 2])
            if params[0]:  # conditionally apply T gate
                qml.T(0)
            return qml.state()

        return optimized_circuit(*args, **kwargs)
    return wrapper

@reduce_t_gate_depth
def original_circuit(param):
    @qml.qnode(qml.device("default.qubit"))
    def circuit():
        qml.Hadamard(0)
        qml.T(0)
        qml.CNOT(wires=[0, 1])
        qml.T(1)
        qml.CNOT(wires=[1, 2])
        return qml.state()

    return circuit()

