import pennylane as qml
import numpy as np

def batch_jvp(tapes, vectors, reduction='sum'):
    dev = qml.device('default.qubit', wires=1)

    @qml.qnode(dev)
    def circuit(params):
        qml.RX(params[0], wires=0)
        return qml.expval(qml.PauliZ(0))

    results = []
    for tape, vector in zip(tapes, vectors):
        with qml.tape.JacobianTape() as tape:
            circuit(tape.parameters)
        jvp = np.dot(tape.jacobian(), vector)

        if reduction == 'sum':
            results.append(np.sum(jvp))
        elif reduction == 'mean':
            results.append(np.mean(jvp))
        else:
            results.append(jvp)

    return results

# Example usage
tapes = [qml.tape.QuantumTape() for _ in range(3)]
vectors = [np.array([1.0]), np.array([0.5]), np.array([0.2])]
results = batch_jvp(tapes, vectors)
print(results)

