@qml.qnode(dev)
def ghz_state():
    # Apply Hadamard gate to the first qubit
    qml.Hadamard(wires=0)
    # Apply CNOT gates to create the GHZ state
    for i in range(4):
        qml.CNOT(wires=[i, i + 1])

