# Define the device
dev = qml.device("default.qubit", wires=1)

@qml.qnode(dev)
def bomb_tester(angle):
    qml.RX(angle, wires=0)
    return qml.sample(qml.PauliZ(0))

def is_bomb():
    return np.random.rand() < 0.5  # 50% chance of being a bomb

def simulate(trials=10000):
    success_count = 0
    for _ in range(trials):
        if is_bomb():
            result = bomb_tester(np.pi)  # Rotate to detect bomb
        else:
            result = bomb_tester(0)  # No rotation for no bomb
        if result == -1:  # Measurement indicates bomb detected
            success_count += 1
    return success_count / trials

success_rate = simulate()
print(f"Success rate of detecting bombs: {success_rate}")

