import pennylane as qml
import pytest
import numpy as np

# Define a QNode for testing
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev)
def circuit_with_gates(gate_sequence):
    for gate in gate_sequence:
        if gate == 'H':
            qml.Hadamard(wires=0)
        elif gate == 'X':
            qml.PauliX(wires=0)
        elif gate == 'Z':
            qml.PauliZ(wires=0)
    return qml.state()

# Test cases for cancel_inverses transformation
@pytest.mark.parametrize("gate_sequence, expected_state", [
    (['H', 'H'], np.array([1, 0, 0, 0])),  # H followed by H cancels
    (['X', 'X'], np.array([1, 0, 0, 0])),  # X followed by X cancels
    (['Z', 'Z'], np.array([1, 0, 0, 0])),  # Z followed by Z cancels
    (['H', 'X', 'H', 'X'], np.array([0, 1, 0, 0])),  # H and X cancel
