import pennylane as qml
import jax
import jax.numpy as jnp
import pytest

# Define a quantum device
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev, interface='jax')
def simple_loop_circuit(n):
    qml.Hadamard(wires=0)
    for i in range(n):
        qml.CNOT(wires=[0, 1])
    return qml.expval(qml.PauliZ(1))

@qml.qnode(dev, interface='jax')
def dynamic_array_loop_circuit(arr):
    for val in arr:
        qml.RX(val, wires=0)
    return qml.expval(qml.PauliZ(0))

@qml.qnode(dev, interface='jax')
def nested_loop_circuit(n):
    for i in range(n):
        for j in range(n):
            qml.CNOT(wires=[0, 1])
    return qml.expval(qml.PauliZ(1))

@qml.qnode(dev, interface='jax')
def gradient_loop_circuit(n):
    qml.Hadamard(wires=0)
    for i in range(n):
        qml.RX(jnp.pi / n, wires=0)
    return qml.expval(qml.PauliZ(0))

def test_simple_loop():
    result = simple_loop_circuit(3)
    assert jnp.isclose(result, 0.0)

def test_dynamic_array_loop():
    arr = jnp.array([0.1, 0.2, 0.3])
    result = dynamic_array_loop_circuit(arr)
    assert jnp.isclose(result, jnp.cos(0.3))

def test_nested_loop():
    result = nested_loop_circuit(2)
    assert jnp.isclose(result, 1.0)

def test_gradient_loop():
    result = gradient_loop_circuit(4)
    assert jnp.isclose(result, jnp.cos(jnp.pi / 4))

