# Define two QNodes for testing
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev)
def circuit1(params):
    qml.RY(params[0], wires=0)
    qml.RY(params[1], wires=1)
    return qml.state()

@qml.qnode(dev)
def circuit2(params):
    qml.RY(params[0] + np.pi/4, wires=0)
    qml.RY(params[1] + np.pi/4, wires=1)
    return qml.state()

def trace_distance(state1, state2):
    """Compute the trace distance between two quantum states."""
    rho1 = np.outer(state1, np.conj(state1))
    rho2 = np.outer(state2, np.conj(state2))
    return 0.5 * np.trace(np.abs(rho1 - rho2))

@pytest.mark.parametrize("params", [([0.1, 0.2]), ([0.5, 0.6]), ([1.0, 1.2])])
def test_trace_distance(params):
    state1 = circuit1(params)
    state2 = circuit2(params)
    distance = trace_distance(state1, state2)
    assert distance >= 0
    assert distance <= 1

