import pytest
import pennylane as qml
import numpy as np

# Define a simple quantum circuit
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev)
def circuit(theta):
    qml.RX(theta, wires=0)
    qml.RY(theta, wires=1)
    return qml.state()

# Function to calculate purity
def purity(state):
    rho = np.outer(state, np.conj(state))
    return np.trace(np.dot(rho, rho))

# Test for purity
def test_purity():
    theta = np.pi / 4
    state = circuit(theta)
    assert np.isclose(purity(state), 1.0, atol=1e-2)

# Test for gradient
def test_gradient():
    theta = np.pi / 4
    gradient = qml.grad(circuit)(theta)
    assert gradient.shape == (2,)

# Test for invalid input
def test_invalid_input():
    with pytest.raises(ValueError):
        circuit("invalid_theta")

# Test for different devices
@pytest.mark.parametrize("device_name", ["default.qubit", "lightning.qubit"])
