    def circuit(theta):
        qml.RX(theta, wires=0)
        qml.RY(theta, wires=1)
        return qml.state()

    theta = np.pi / 4
    state = circuit(theta)
    assert np.isclose(purity(state), 1.0, atol=1e-2)

# Test for different differentiation methods
@pytest.mark.parametrize("method", ["finite-diff", "backprop"])
def test_differentiation_methods(method):
