import pennylane as qml
import pytest
import numpy as np

# Define the quantum circuit with IsingXX gate
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev, interface='autograd')
def circuit(theta):
    qml.IsingXX(theta, wires=[0, 1])
    return qml.expval(qml.PauliZ(0))

@qml.qnode(dev, interface='jax')
def circuit_jax(theta):
    qml.IsingXX(theta, wires=[0, 1])
    return qml.expval(qml.PauliZ(0))

@qml.qnode(dev, interface='torch')
def circuit_torch(theta):
    qml.IsingXX(theta, wires=[0, 1])
    return qml.expval(qml.PauliZ(0))

@qml.qnode(dev, interface='tf')
def circuit_tf(theta):
    qml.IsingXX(theta, wires=[0, 1])
    return qml.expval(qml.PauliZ(0))

# Function to compute purity
def purity(rho):
    return np.trace(rho @ rho)

# Test the purity of the circuit
def test_purity():
    theta = np.pi / 4
    result = circuit(theta)
    rho = np.array([[0.5 * (1 + result), 0], [0, 0.5 * (1 - result)]])
    assert np.isclose(purity(rho), 1.0, atol=1e-2)

# Test gradients using different interfaces
@pytest.mark.parametrize("interface", ['autograd', 'jax', 'torch', 'tf'])
def test_gradient(interface):
    if interface == 'autograd':
        import autograd.numpy as anp
        theta = anp.array(0.1, requires_grad=True)
        grad = qml.grad(circuit)(theta)
    elif interface == 'jax':
        import jax.numpy as jnp
        theta = jnp.array(0.1)
        grad = qml.grad(circuit_jax)(theta)
    elif interface == 'torch':
        import torch
        theta = torch.tensor(0.1, requires_grad=True)
        grad = qml.grad(circuit_torch)(theta)
    elif interface == 'tf':
        import tensorflow as tf
        theta = tf.Variable(0.1)
        with tf.GradientTape() as tape:
            output = circuit_tf(theta)
        grad = tape.gradient(output, theta)

    assert grad is not None

